<script setup>defineProps({modelValue:{type:[String,Number],default:''},options:{type:Array,default:()=>[]},label:String,disabled:Boolean});defineEmits(['update:modelValue']);const val=o=>typeof o==='object'?o.value:o,txt=o=>typeof o==='object'?o.label:o</script><template><label class="field"><span v-if="label">{{label}}</span><select :value="modelValue" :disabled="disabled" @change="$emit('update:modelValue',$event.target.value)"><option v-for="o in options" :key="val(o)" :value="val(o)">{{txt(o)}}</option></select></label></template><style scoped>.field{display:grid;gap:6px;font-size:11px;color:var(--text-secondary)}select{padding:9px;border:1px solid var(--line-strong);border-radius:var(--radius-md);background:var(--surface);color:var(--text)}</style>